{
  "headline": "Cadence has a strong gross margin and a credible default-alive trajectory, but the model needs significant depth before investor conversations.",
  "investor_talking_points": [
    "We're generating $58.5k MRR growing at 8% month-over-month with 75% gross margins — the unit economics foundation is there.",
    "At $120k monthly burn and $1.5M in the bank, our model projects reaching cash-flow breakeven around month 19 without additional capital.",
    "We need to build out the model with CAC data, headcount breakdown, and 24-month projections — we know what's missing and we're filling it."
  ],
  "lenses": {
    "runway": {
      "callout": "Default-alive on current growth trajectory — projected to reach breakeven before cash runs out (~month 19 from June 2026).",
      "highlight": "Static runway of 12.5 months at today's burn; slow-growth scenario tightens this to 13 months before cash-out.",
      "watch_out": "The 8% monthly growth assumption is the single biggest driver — if growth slows to 4%, the default-alive story breaks."
    },
    "unit_economics": {
      "callout": "75% gross margin is strong for B2B SaaS at seed stage — well above the 60-70% benchmark.",
      "watch_out": "CAC and LTV/CAC ratio cannot be computed from the model as-is — no customer acquisition cost data is present, which will be a gap for investors."
    }
  }
}

